
.play-shell {
  width: 100%;
  background: linear-gradient(135deg, rgba(2, 6, 23, 0.88), rgba(15, 23, 42, 0.92));
  border: 1px solid rgba(59, 130, 246, 0.25);
  border-radius: 20px;
  box-shadow: 0 20px 50px rgba(15, 23, 42, 0.45);
  backdrop-filter: blur(18px);
  padding: 0;
}

.play-header {
  padding: 14px 18px;
  border-bottom: 1px solid rgba(59, 130, 246, 0.2);
}

.play-stage {
  border-bottom: 1px solid rgba(59, 130, 246, 0.15);
  padding: 12px 14px 14px;
}

.play-stage-media {
  width: 100%;
  aspect-ratio: 21 / 9;
  overflow: hidden;
  border-radius: 16px;
}

.play-body {
  padding: 14px 16px 0;
  display: grid;
  gap: 12px;
}

.play-log-card {
  border-radius: 18px;
  border: 1px solid rgba(148, 163, 184, 0.25);
  background: rgba(2, 6, 23, 0.65);
}

.play-log-card.link-market {
  border-color: rgba(16, 185, 129, 0.45);
  box-shadow:
    0 0 0 1px rgba(16, 185, 129, 0.2),
    0 12px 30px rgba(16, 185, 129, 0.12);
}

.play-log-head {
  padding: 12px 16px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.2);
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: space-between;
  align-items: center;
}

.play-tools {
  padding: 8px 16px;
  border-bottom: 1px dashed rgba(148, 163, 184, 0.25);
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
  font-size: 12px;
  color: rgba(226, 232, 240, 0.65);
}

.play-log-content {
  padding: 16px;
  font-size: 14px;
  line-height: 1.7;
  color: #e2e8f0;
  white-space: pre-wrap;
}

.play-input {
  padding: 14px 16px 18px;
}

.play-input-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
}

.play-input-field {
  width: 100%;
  border-radius: 16px;
  border: 1px solid rgba(148, 163, 184, 0.35);
  background: rgba(2, 6, 23, 0.75);
  padding: 12px 14px;
  color: #fff;
  font-size: 14px;
  outline: none;
}

.play-input-field:focus {
  border-color: rgba(96, 165, 250, 0.6);
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2);
}

.play-input.link-market .play-input-field {
  border-color: rgba(16, 185, 129, 0.5);
  box-shadow: 0 0 0 2px rgba(16, 185, 129, 0.15);
}

.play-send {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border-radius: 16px;
  padding: 12px 18px;
  border: 1px solid rgba(59, 130, 246, 0.35);
  background: linear-gradient(135deg, rgba(59, 130, 246, 0.8), rgba(139, 92, 246, 0.85));
  color: #fff;
  font-weight: 700;
  cursor: pointer;
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.play-send:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.play-send:not(:disabled):hover {
  transform: translateY(-1px);
  box-shadow: 0 12px 24px rgba(37, 99, 235, 0.35);
}

@media (max-width: 768px) {
  .play-shell {
    border-radius: 12px;
  }
  .play-input-row {
    grid-template-columns: 1fr;
  }
  .play-send {
    justify-content: center;
  }
}
