
.service-view {
  width: 100%;
  height: auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 18px;
  background:
    radial-gradient(circle at top left, rgba(248, 113, 113, 0.18), transparent 50%),
    linear-gradient(135deg, rgba(2, 6, 23, 0.98), rgba(15, 23, 42, 0.96));
  color: #e2e8f0;
}

.service-hero {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
  justify-content: space-between;
  padding: 16px;
  border-radius: 18px;
  border: 1px solid rgba(248, 113, 113, 0.25);
  background: rgba(15, 23, 42, 0.85);
}

.hero-title {
  font-size: 18px;
  font-weight: 800;
  display: flex;
  align-items: center;
  gap: 8px;
}

.hero-sub {
  font-size: 12px;
  color: rgba(226, 232, 240, 0.6);
}

.hero-time {
  color: rgba(148, 163, 184, 0.7);
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.btn-outline,
.btn-ghost,
.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border-radius: 14px;
  padding: 8px 12px;
  border: 1px solid rgba(148, 163, 184, 0.3);
  background: rgba(15, 23, 42, 0.8);
  color: #e2e8f0;
  font-size: 12px;
  font-weight: 700;
}

.btn-primary {
  background: linear-gradient(135deg, rgba(248, 113, 113, 0.85), rgba(239, 68, 68, 0.85));
  border-color: rgba(248, 113, 113, 0.5);
}

.loading-state,
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 40px 12px;
  text-align: center;
  color: rgba(226, 232, 240, 0.6);
}

.spinner {
  width: 42px;
  height: 42px;
  border: 3px solid rgba(148, 163, 184, 0.3);
  border-top-color: rgba(248, 113, 113, 0.8);
  border-radius: 50%;
  animation: spin 1s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.service-layout {
  display: grid;
  grid-template-columns: minmax(0, 280px) minmax(0, 1fr);
  gap: 16px;
}

@media (max-width: 900px) {
  .service-layout {
    grid-template-columns: 1fr;
  }
}

.order-list {
  border-radius: 18px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  background: rgba(15, 23, 42, 0.8);
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.order-list-title {
  font-size: 13px;
  font-weight: 700;
}

.order-list-body {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.order-card {
  border-radius: 14px;
  padding: 12px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  background: rgba(2, 6, 23, 0.65);
  color: #e2e8f0;
  text-align: left;
  display: grid;
  gap: 6px;
}

.order-card.active {
  border-color: rgba(248, 113, 113, 0.5);
  box-shadow: 0 8px 20px rgba(248, 113, 113, 0.2);
}

.order-name {
  font-size: 14px;
  font-weight: 700;
}

.order-meta {
  font-size: 11px;
  color: rgba(226, 232, 240, 0.6);
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.order-progress {
  display: flex;
  align-items: center;
  gap: 8px;
}

.progress-text {
  font-size: 10px;
  color: rgba(226, 232, 240, 0.7);
}

.order-detail {
  border-radius: 18px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  background: rgba(15, 23, 42, 0.85);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.detail-hero {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.detail-name {
  font-size: 20px;
  font-weight: 800;
}

.detail-sub {
  font-size: 12px;
  color: rgba(226, 232, 240, 0.6);
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.detail-tags {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.tag {
  font-size: 10px;
  padding: 4px 8px;
  border-radius: 999px;
  background: rgba(248, 113, 113, 0.2);
  color: #fecaca;
}

.tag.accent {
  background: rgba(59, 130, 246, 0.2);
  color: #bfdbfe;
}

.tag.muted {
  background: rgba(148, 163, 184, 0.2);
  color: rgba(226, 232, 240, 0.7);
}

.metric-grid {
  display: grid;
  gap: 10px;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
}

.metric-card {
  border-radius: 14px;
  padding: 12px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  background: rgba(2, 6, 23, 0.65);
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.metric-label {
  font-size: 11px;
  color: rgba(226, 232, 240, 0.6);
}

.metric-value {
  font-size: 16px;
  font-weight: 700;
  color: #e2e8f0;
}

.progress-bar {
  width: 100%;
  height: 6px;
  border-radius: 999px;
  background: rgba(148, 163, 184, 0.2);
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: rgba(248, 113, 113, 0.8);
}

.package-card {
  border-radius: 16px;
  padding: 14px;
  border: 1px solid rgba(248, 113, 113, 0.25);
  background: rgba(2, 6, 23, 0.7);
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.package-title {
  font-size: 12px;
  color: rgba(226, 232, 240, 0.6);
}

.package-price {
  font-size: 22px;
  font-weight: 800;
  color: #fecaca;
}

.package-name {
  font-size: 13px;
  color: rgba(226, 232, 240, 0.7);
}

.package-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.detail-panel {
  border-radius: 16px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  background: rgba(2, 6, 23, 0.65);
  padding: 0;
  overflow: hidden;
}

.detail-panel summary {
  list-style: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 12px 14px;
  font-size: 12px;
  font-weight: 700;
}

.detail-panel summary::-webkit-details-marker {
  display: none;
}

.panel-body {
  padding: 12px 14px;
  display: grid;
  gap: 10px;
}

.clothing-grid {
  display: grid;
  gap: 10px;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
}

.clothing-item {
  display: flex;
  gap: 10px;
  align-items: center;
  padding: 10px;
  border-radius: 12px;
  background: rgba(15, 23, 42, 0.8);
  border: 1px solid rgba(148, 163, 184, 0.2);
}

.clothing-icon {
  color: #fca5a5;
}

.clothing-key {
  font-size: 11px;
  color: rgba(226, 232, 240, 0.6);
}

.clothing-value {
  font-size: 12px;
  font-weight: 600;
  color: #e2e8f0;
}

.info-line {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.info-label {
  font-size: 11px;
  color: rgba(226, 232, 240, 0.6);
}

.info-value {
  font-size: 12px;
  color: #e2e8f0;
  line-height: 1.5;
  word-break: break-word;
}

.empty-text {
  font-size: 12px;
  color: rgba(226, 232, 240, 0.6);
}

.status-active {
  color: #4ade80;
}

.status-completed {
  color: #60a5fa;
}

.status-pending {
  color: #f59e0b;
}
