
.home-view {
  width: 100%;
  height: auto;
  display: flex;
  flex-direction: column;
  gap: 20px;
  padding: 18px;
  background:
    radial-gradient(circle at top left, rgba(30, 58, 138, 0.25), transparent 50%),
    linear-gradient(135deg, rgba(2, 6, 23, 0.98), rgba(15, 23, 42, 0.96));
  color: #e2e8f0;
}

.home-hero {
  display: grid;
  gap: 16px;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  align-items: stretch;
}

.hero-main,
.hero-guide {
  border-radius: 20px;
  padding: 18px;
  border: 1px solid rgba(59, 130, 246, 0.2);
  background: rgba(15, 23, 42, 0.85);
  box-shadow: 0 14px 30px rgba(15, 23, 42, 0.35);
}

.brand-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
  margin-bottom: 12px;
}

.brand-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  border-radius: 999px;
  background: rgba(255, 195, 0, 0.18);
  color: #fde68a;
  font-weight: 700;
  font-size: 12px;
}

.brand-version {
  font-size: 12px;
  color: rgba(148, 163, 184, 0.8);
}

.hero-title {
  font-size: 26px;
  font-weight: 800;
  margin: 0 0 8px 0;
}

.hero-subtitle {
  font-size: 13px;
  color: rgba(226, 232, 240, 0.75);
  line-height: 1.6;
  margin: 0;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 16px;
}

.btn-primary,
.btn-outline,
.btn-ghost {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border-radius: 14px;
  padding: 10px 14px;
  border: 1px solid transparent;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
}

.btn-primary {
  background: linear-gradient(135deg, rgba(59, 130, 246, 0.9), rgba(139, 92, 246, 0.9));
  color: #ffffff;
  border-color: rgba(59, 130, 246, 0.4);
}

.btn-outline {
  background: rgba(15, 23, 42, 0.9);
  border: 1px solid rgba(148, 163, 184, 0.3);
  color: #e2e8f0;
}

.btn-ghost {
  background: rgba(15, 23, 42, 0.6);
  border: 1px solid rgba(148, 163, 184, 0.2);
  color: #e2e8f0;
}

.hero-guide .guide-title {
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 12px;
}

.guide-steps {
  display: grid;
  gap: 12px;
}

.guide-step {
  display: flex;
  gap: 12px;
  padding: 10px 12px;
  border-radius: 14px;
  background: rgba(2, 6, 23, 0.6);
  border: 1px solid rgba(148, 163, 184, 0.2);
}

.step-index {
  font-weight: 800;
  color: #93c5fd;
}

.step-title {
  font-size: 13px;
  font-weight: 700;
  margin-bottom: 4px;
}

.step-desc {
  font-size: 12px;
  color: rgba(226, 232, 240, 0.6);
}

.command-center {
  display: grid;
  gap: 16px;
  grid-template-columns: minmax(0, 1.4fr) minmax(0, 0.6fr);
}

@media (max-width: 900px) {
  .command-center {
    grid-template-columns: 1fr;
  }
}

.command-card {
  border-radius: 20px;
  padding: 16px;
  border: 1px solid rgba(59, 130, 246, 0.2);
  background: rgba(15, 23, 42, 0.85);
  box-shadow: 0 14px 30px rgba(15, 23, 42, 0.35);
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.command-head {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
  justify-content: space-between;
}

.command-title {
  font-size: 15px;
  font-weight: 700;
}

.command-desc {
  font-size: 12px;
  color: rgba(226, 232, 240, 0.6);
}

.command-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.search-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  padding: 10px 12px;
  border-radius: 14px;
  border: 1px solid rgba(148, 163, 184, 0.25);
  background: rgba(2, 6, 23, 0.6);
}

.search-row input {
  background: transparent;
  border: none;
  outline: none;
  color: #e2e8f0;
  font-size: 13px;
}

.quick-grid {
  display: grid;
  gap: 10px;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
}

.quick-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border-radius: 14px;
  padding: 10px 12px;
  border: 1px solid rgba(148, 163, 184, 0.25);
  background: rgba(2, 6, 23, 0.6);
  color: #e2e8f0;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}

.side-stack {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.side-card {
  border-radius: 18px;
  padding: 16px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  background: rgba(15, 23, 42, 0.8);
  box-shadow: 0 12px 24px rgba(15, 23, 42, 0.3);
}

.card-title {
  font-size: 13px;
  font-weight: 700;
  display: flex;
  gap: 8px;
  align-items: center;
  margin-bottom: 10px;
}

.card-actions {
  display: grid;
  gap: 8px;
}

.notice-details summary {
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  list-style: none;
  padding: 8px 0;
  font-size: 12px;
  color: rgba(226, 232, 240, 0.75);
}

.notice-details summary::-webkit-details-marker {
  display: none;
}

.notice-body {
  display: grid;
  gap: 8px;
  margin-top: 8px;
}

.notice-item {
  font-size: 12px;
  line-height: 1.5;
  color: rgba(226, 232, 240, 0.7);
}

.notice-item .tag {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 2px 6px;
  border-radius: 6px;
  margin-right: 6px;
  font-size: 10px;
  font-weight: 700;
  background: rgba(59, 130, 246, 0.2);
  color: #93c5fd;
}
