
.panel-overlay {
  position: fixed;
  inset: 0;
  z-index: 5200;
  background: rgba(2, 6, 23, 0.6);
  padding: 16px;
}

.panel-shell {
  width: min(1120px, 100%);
  margin: 0 auto;
  background: linear-gradient(135deg, rgba(15, 23, 42, 0.96), rgba(2, 6, 23, 0.98));
  border: 1px solid rgba(59, 130, 246, 0.2);
  border-radius: 20px;
  box-shadow: 0 25px 60px rgba(15, 23, 42, 0.5);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.panel-head-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.panel-title {
  display: flex;
  align-items: center;
  gap: 12px;
  color: #e2e8f0;
}

.panel-icon {
  width: 40px;
  height: 40px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  background: rgba(59, 130, 246, 0.12);
  color: #93c5fd;
}

.panel-title .title {
  font-weight: 700;
  font-size: 16px;
}

.panel-title .sub {
  font-size: 12px;
  color: rgba(148, 163, 184, 0.7);
}

.panel-close {
  border-radius: 14px;
  padding: 8px 12px;
  border: 1px solid rgba(148, 163, 184, 0.3);
  background: rgba(15, 23, 42, 0.8);
  color: #e2e8f0;
  font-size: 12px;
  font-weight: 600;
}

.panel-layout {
  display: grid;
  grid-template-columns: minmax(140px, 180px) minmax(0, 1fr);
  gap: 16px;
}

.panel-tabs {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.panel-tab {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border-radius: 14px;
  padding: 10px 12px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  background: rgba(15, 23, 42, 0.8);
  color: rgba(226, 232, 240, 0.85);
  font-size: 13px;
  font-weight: 600;
  transition: all 0.2s ease;
}

.panel-tab.active {
  border-color: rgba(59, 130, 246, 0.5);
  background: rgba(59, 130, 246, 0.2);
  color: #e0f2fe;
}

.panel-main {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.panel-section {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.panel-card {
  border-radius: 16px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  background: rgba(15, 23, 42, 0.75);
  padding: 14px;
  color: #e2e8f0;
}

.panel-card-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 8px;
}

.panel-card-desc {
  font-size: 12px;
  color: rgba(226, 232, 240, 0.6);
  margin-bottom: 10px;
}

.panel-grid {
  display: grid;
  gap: 12px;
}

.panel-actions {
  display: grid;
  gap: 8px;
}

.panel-action {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border-radius: 12px;
  padding: 10px 12px;
  border: 1px solid rgba(148, 163, 184, 0.25);
  background: rgba(30, 41, 59, 0.6);
  color: #e2e8f0;
  font-size: 12px;
  font-weight: 600;
}

.panel-nav-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 8px;
}

.panel-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 10px;
  border-radius: 12px;
  border: 1px solid rgba(148, 163, 184, 0.25);
  background: rgba(30, 41, 59, 0.5);
  color: #e2e8f0;
  font-size: 12px;
  font-weight: 600;
}

@media (max-width: 900px) {
  .panel-layout {
    grid-template-columns: 1fr;
  }
  .panel-tabs {
    flex-direction: row;
    flex-wrap: wrap;
  }
}
